import {gatherUntil, sell, note, orient} from 'play';
import type {Outcome, Want} from 'play';

export default async function main(): Promise<Outcome<unknown>> {
  // Sanity: confirm where we are before committing to the belt.
  const here = await orient();
  note(
    `starting from ${here.now?.location?.poi_name ?? 'somewhere'} ` +
    `(docked: ${here.now?.location?.docked_at ?? 'no'})`
  );

  // Out and back until the store holds 200 iron_ore, at most 4 trips.
  const run = await gatherUntil({
    poi: 'unknown_edge_mineral_fields',
    until: {item: 'iron_ore', quantity: 200},
    maxTrips: 4,
  });
  if (run.status === 'refused') {
    note(`gather refused: ${run.why ?? ''}`);
    return run;
  }
  if (run.status !== 'done') {
    note(`gather ended ${run.status}: ${run.why ?? ''}`);
  }

  // Every row the trips settled, except iron_ore.
  const settled = run.detail?.settled ?? [];
  const take: Want[] = settled
    .filter((row) => row.item_id !== 'iron_ore' && row.quantity > 0)
    .map((row) => ({item_id: row.item_id, quantity: row.quantity}));

  if (!take.length) {
    note('nothing but iron_ore settled; nothing to sell');
    return run;
  }
  note(`selling ${take.map((w) => `${w.quantity} ${w.item_id}`).join(', ')} from the store`);

  // Sells from the store (the docked counter is frontier_station, where the trips stowed).
  return sell(take, {from: 'store'});
}
