import {orient, goTo, scout, hunt, disengage, note} from 'play';

export default async function main() {
  const start = await orient();
  const here = start.detail.present.location;

  // Get to sol_nebula (a POI id: fly there; no base implied, so the hunt runs in open space).
  const flight = await goTo('sol_nebula');
  if (flight.status !== 'done') return flight;

  // Build the look list: every POI in the system we have arrived in, fauna-favored types first.
  // `hunt` bounds the hops by fuel, so an over-eager list only costs the looks it can afford.
  const system = here.system_id;
  let look: string[] | undefined;
  if (system) {
    const scouted = await scout(system);
    const likely = /nebula|cloud|belt|field|asteroid/i;
    look = [...(scouted.detail.pois ?? [])]
      .sort((a, b) => (likely.test(a.type) ? 0 : 1) - (likely.test(b.type) ? 0 : 1))
      .map(p => p.id);
    if (!look.length) look = undefined;
  }
  if (!look) look = ['sol_nebula'];   // the one place the task named

  // The hunt: 2 fights, spanning that list, with whatever prey is there.
  let out;
  try {
    out = await hunt({fights: 2, look});
  } catch (err) {
    // A thrown error is handled the same as a refused/failed hunt for the purposes of the task:
    // we still run disengage() and return an Outcome-shaped result.
    note(`hunt threw: ${err instanceof Error ? err.message : String(err)}`);
    out = {status: 'failed' as const, did: 'hunt threw', why: `hunt threw: ${err instanceof Error ? err.message : String(err)}`};
  }

  // Whatever the hunt returned or threw — done, refused, failed — disengage() runs here, after it,
  // so no battle keeps the ship when the program ends.
  const broke = await disengage();

  return Object.assign(out, {did: out.did + `; ${broke ? 'disengaged, battle ended' : 'disengaged'}`});
}
```

