import {orient, scout, goTo, hunt, service, stow, disengage, note, type Outcome} from 'play';

/**
 * The whole evening: one flight to sol_nebula, two fights where the prey is, and a
 * `finally` that guarantees disengage() runs on every path — a done, refused or failed
 * hunt, and a thrown error alike. `finally` runs after the try completes, returns or
 * throws, and returns nothing, so it can never overwrite the hunt Outcome we hand back.
 */
export default async function main(): Promise<Outcome<unknown>> {
  let huntOutcome: Outcome<unknown>;
  try {
    // 1 — the flight, first. `did` here is "flew to <POI>…", undocked; it is a leg to
    // wherever the prey stands, not a dock, so there is nothing to service before the
    // fight and no dock to return to afterwards.
    const here = await goTo('sol_nebula');
    if (here.status !== 'done') return here;

    // 2 — the hunt, at the POI we just landed on. Two fights; `species` is left unset
    //    (a preference, not a requirement) so a quiet nebula still earns both with
    //    whatever the world does not decline, rather than walking off over a mismatch.
    huntOutcome = await hunt({fights: 2});

    // The trip's proper close, in the normal case: refuel, hull up, the loot into the
    // hold and out of the story. One call; it changes nothing else, and Tired and the
    // walk-away line have already guarded the hull all the way through.
    const take = huntOutcome.gained?.items;
    if (take && take.length) await stow(take);
    await service();
    note('take stowed and the ship resupplied');
  } finally {
    // 3 — the one call the task says must run at the end of the program, on every path:
    // a done hunt, a refused or failed one, or an error thrown out of goTo or hunt.
    // A move refused `in_battle` is the only real reason left, and it is exactly what
    // `disengage()` exists for. Awaited for completeness; it breaks the battle off,
    // waits out the end, and returns nothing that main would hand back, so it cannot
    // disturb the hunt Outcome. Nothing to break off means a refused, which is
    // harmless to a completed hunt.
    const off = await disengage();
    if (off.status !== 'done') note(`disengage did not end clean: ${off.why ?? off.status}`);
  }
  return huntOutcome;
}
