import {orient, scout, goTo, disengage, hunt, note} from 'play';

export default async function main() {
  const start = await orient();
  const systemId = start.detail.present.location.system_id;

  let ret;
  try {
    ret = await goTo('sol_nebula');
  } catch (err) {
    note(`goTo sol_nebula threw: ${err instanceof Error ? err.message : String(err)}`);
    return disengage();   // worst case: no hunt, but the escape fires
  }

  if (ret.status !== 'done') {
    note(`goTo sol_nebula did not land (status: ${ret.status}, why: ${ret.why ?? 'n/a'})`);
    return disengage();   // stand down, then return the go-to Outcome
  }

  const here = await scout();
  const likely = /nebula|cloud|belt|field|asteroid/;
  const habitats = [...here.detail.pois]
    .sort((a, b) => (likely.test(a.type) ? 0 : 1) - (likely.test(b.type) ? 0 : 1))
    .map(p => p.id);
  const look = habitats.length ? habitats : [here.detail.pois[0].id];

  let h;
  try {
    h = await hunt({fights: 2, look, poi: 'sol_nebula'});
  } catch (err) {
    note(`hunt threw: ${err instanceof Error ? err.message : String(err)}`);
    return disengage();   // a thrown error — the escape fires, nothing to return
  }

  note(
    `hunt ended: ${h.detail.ended ?? 'n/a'} (status: ${h.status}, ${h.detail.fights?.length ?? 0} fight(s))`,
  );

  return disengage();  // the one call after the hunt, whatever it was
}
```

The `try`/`catch` around `goTo` and `hunt` catches a thrown error (the "or a thrown error" case) so the escape still runs; a plain non-done, refused or failed Outcome skips the catch but still lands on the final `return disengage()`. Per the requirement, the hunt Outcome is what the program returns (the hunt's Outcome is what `disengage()` resolves to, so it is both the last call and the returned value).

